const card = "rounded-2xl border border-stroke bg-surface p-5 shadow-[0_12px_36px_rgba(10,20,42,.1)]";
const subtle = "text-slate-500";
const primary = "inline-flex min-h-10 items-center justify-center rounded-xl bg-electric px-4 text-xs font-semibold text-white transition hover:bg-electric-bright disabled:cursor-not-allowed disabled:opacity-50";
const secondary = "inline-flex min-h-10 items-center justify-center rounded-xl border border-stroke bg-surface-muted px-4 text-xs font-semibold text-foreground transition hover:border-electric/40 disabled:opacity-50";
const inputClass = "min-h-10 w-full rounded-xl border border-stroke bg-surface-muted px-3 text-xs text-foreground outline-none focus:border-electric focus:ring-2 focus:ring-electric/15";
const eyebrow = "text-[10px] font-semibold uppercase tracking-[.16em] text-slate-500";
type Obj = Record<string, unknown>;
function obj(value: unknown): Obj { return value && typeof value === "object" && !Array.isArray(value) ? value as Obj : {}; }
function rows(value: unknown): Obj[] { return Array.isArray(value) ? value.map(obj) : []; }
function stringItems(value: unknown): string[] { return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : []; }
function text(value: unknown, fallback = "—"): string { return typeof value === "string" && value ? value : fallback; }
function number(value: unknown): number { return typeof value === "number" && Number.isFinite(value) ? value : 0; }
function date(value: unknown): string { if (typeof value !== "string") return "—"; const parsed = new Date(value); return Number.isNaN(parsed.valueOf()) ? "—" : parsed.toLocaleString(); }
function count(value: unknown): string { return new Intl.NumberFormat().format(number(value)); }
function title(value: string): string { return value.replaceAll("_", " ").replace(/\b\w/g, (c) => c.toUpperCase()); }
function unwrapItems(value: Obj): Obj[] { return rows(value.items); }
function getErr(error: unknown): string { return error instanceof Error ? error.message : "The platform request could not be completed."; }
function readPath(path: string): { area: string; id?: string } {
  const parts = path.split("/").filter(Boolean).slice(2);
  const area = parts[0] ?? "";
  const id = parts[1];
  return id === undefined ? { area } : { area, id };
}

function PlatformShell({ children, active, capabilities = {} }: { children: ReactNode; active: string; capabilities?: Readonly<Record<string, boolean>> }) {
  const links: Array<{ href: string; label: string; icon: string; capability: string; tourId?: string }> = [
    { href: "/app/platform-admin", label: "Command center", icon: "◫", capability: "platform.dashboard.read" },
    { href: "/app/platform-admin/tenants", label: "Tenants", icon: "▦", capability: "platform.tenants.read", tourId: "platform-nav-tenants" },
    { href: "/app/platform-admin/users", label: "Users", icon: "♙", capability: "platform.users.read", tourId: "platform-nav-users" },
    { href: "/app/platform-admin/billing", label: "Subscriptions", icon: "◒", capability: "platform.billing.manage" },
    { href: "/app/platform-admin/usage", label: "Usage", icon: "▥", capability: "platform.usage.read", tourId: "platform-nav-usage" },
    { href: "/app/platform-admin/health", label: "System health", icon: "⌁", capability: "platform.health.read", tourId: "platform-nav-health" },
    { href: "/app/platform-admin/support", label: "Support", icon: "◌", capability: "platform.support.manage", tourId: "platform-nav-support" },
    { href: "/app/platform-admin/audit", label: "Audit center", icon: "≋", capability: "platform.audit.read", tourId: "platform-nav-audit" },
    { href: "/app/platform-admin/settings", label: "Settings & flags", icon: "⚙", capability: "platform.settings.manage", tourId: "platform-nav-settings" },
  ];
  const visibleLinks = links.filter((item) => capabilities[item.capability] === true);
  const navLink = (link: typeof links[number], mobile = false) => <NavLink end={!mobile && link.href === "/app/platform-admin"} key={link.href} to={link.href} data-tour-id={link.tourId} className={({ isActive }) => mobile
    ? `shrink-0 rounded-lg px-3 py-2 text-[10px] ${isActive ? "bg-electric/10 text-electric-bright" : "text-slate-500"}`
    : `flex items-center gap-3 rounded-lg px-3 py-2.5 text-xs transition ${isActive || active === link.href ? "bg-electric/10 text-electric-bright" : "text-slate-400 hover:bg-surface-hover hover:text-foreground"}`}>
    {!mobile && <span aria-hidden="true">{link.icon}</span>}{link.label}
  </NavLink>;
  return <div className="min-h-screen bg-midnight text-slate-100"><aside className="fixed inset-y-0 left-0 z-20 hidden w-[260px] flex-col border-r border-stroke bg-rail px-5 py-6 lg:flex"><Link to="/app" className="flex items-center gap-3 px-1"><span className="grid size-9 place-items-center rounded-xl bg-electric text-lg font-bold text-white">T</span><span><span className="block font-display text-sm font-semibold text-foreground">Tandem Ads</span><span className="mt-1 block text-[9px] tracking-[.18em] text-slate-500">PLATFORM OPERATIONS</span></span></Link><div className="mt-8 rounded-xl border border-electric/20 bg-electric/5 px-3 py-3"><p className="text-[9px] font-semibold uppercase tracking-[.14em] text-electric-bright">Restricted console</p><p className="mt-1 text-[10px] leading-5 text-slate-500">Access is verified by server-side platform capability.</p></div><nav aria-label="Platform administration" className="mt-7 space-y-1">{visibleLinks.map((link) => navLink(link))}</nav><div className="mt-auto border-t border-stroke pt-4"><div className="px-2 pb-3"><AccountActions /></div><Link to="/app" className="px-2 text-[10px] text-slate-500 hover:text-electric-bright">Return to workspace app →</Link></div></aside><main className="min-h-screen lg:pl-[260px]"><header className="flex min-h-16 items-center justify-between border-b border-stroke/80 px-4 sm:px-7 lg:px-9"><div><p className="text-[10px] tracking-[.12em] text-slate-500">TANDEM ADS <span className="px-2 text-slate-700">/</span> PLATFORM OPERATIONS</p><p className="mt-1 text-xs font-semibold text-foreground">Control center</p></div><div className="flex items-center gap-3"><Link to="/app" className="text-[10px] text-slate-500 hover:text-foreground">Workspace app</Link><ThemeSwitcher /></div></header><div className="border-b border-stroke/70 px-4 py-2 lg:hidden"><nav aria-label="Platform administration mobile" className="flex gap-2 overflow-x-auto">{visibleLinks.map((link) => navLink(link, true))}</nav></div>{children}</main></div>;
}

function Metric({ label, value, detail }: { label: string; value: unknown; detail?: string }) {
  return <article className={`${card} min-h-32`}><p className={eyebrow}>{label}</p><p className="mt-4 font-display text-3xl font-semibold tracking-tight text-foreground">{count(value)}</p>{detail && <p className={`mt-2 text-[10px] ${subtle}`}>{detail}</p>}</article>;
}
function State({ value }: { value: unknown }) {
  const s = text(value, "UNKNOWN"); const color = s === "ACTIVE" || s === "HEALTHY" || s === "RESOLVED" ? "border-emerald-500/25 bg-emerald-500/10 text-emerald-500" : s === "SUSPENDED" || s === "UNAVAILABLE" || s === "CLOSED" ? "border-danger/25 bg-danger/10 text-danger" : s === "UNKNOWN" ? "border-stroke bg-surface-muted text-slate-500" : "border-warning/25 bg-warning/10 text-warning";
  return <span className={`inline-flex rounded-full border px-2.5 py-1 text-[9px] font-semibold uppercase tracking-wide ${color}`}>{title(s)}</span>;
}
function Table({ columns, items, empty = "No records are available." }: { columns: Array<[string, (item: Obj) => React.ReactNode]>; items: Obj[]; empty?: string }) {
  return <div className="overflow-x-auto"><table className="w-full min-w-[700px] border-collapse text-left"><thead><tr className="border-b border-stroke">{columns.map(([name]) => <th className="px-3 py-3 text-[9px] font-semibold uppercase tracking-[.12em] text-slate-500" key={name}>{name}</th>)}</tr></thead><tbody className="divide-y divide-stroke">{items.length ? items.map((item, index) => <tr className="hover:bg-surface-muted/50" key={text(item.id, `${index}`)}>{columns.map(([name, render]) => <td className="px-3 py-3 text-xs text-foreground" key={name}>{render(item)}</td>)}</tr>) : <tr><td className="px-3 py-12 text-center text-xs text-slate-500" colSpan={columns.length}>{empty}</td></tr>}</tbody></table></div>;
}

function useAdminData<T>(load: (() => Promise<T>) | null, scope: string) {
  const [snapshot, setSnapshot] = useState<{ scope: string; data: T | null }>({ scope: "", data: null }); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const data = snapshot.scope === scope ? snapshot.data : null;
  const setData = useCallback((value: T | null) => setSnapshot({ scope, data: value }), [scope]);
  const refresh = useCallback(async () => { if (!load) return; setBusy(true); setError(""); try { setData(await load()); } catch (e) { setError(getErr(e)); } finally { setBusy(false); } }, [load, setData]);
  useEffect(() => { void refresh(); }, [refresh]);
  return { data, error, busy, refresh, setData, setError };
}

export function PlatformAdminPage() {
  const { session, loading: authLoading } = useAuth(); const location = useLocation(); const route = readPath(location.pathname);
  const token = session?.access_token ?? ""; const userId = session?.user.id ?? "";
  const [accessState, setAccessState] = useState<{ userId: string; value: { allowed: boolean; capabilities: Record<string, boolean> } } | null>(null); const [accessError, setAccessError] = useState("");
  const access = accessState?.userId === userId ? accessState.value : null;
  useEffect(() => { let active = true; setAccessState(null); setAccessError(""); if (!token || !userId) return; void getPlatformAdminAccess(token).then((value) => { if (active) setAccessState({ userId, value }); }).catch((error) => { if (active) { setAccessError(getErr(error)); setAccessState({ userId, value: { allowed: false, capabilities: {} } }); } }); return () => { active = false; }; }, [token, userId]);
  const [savedTourState, setSavedTourState] = useState<{ userId: string; progress: PlatformTourProgressState | null } | null>(null); const [tourOpen, setTourOpen] = useState(false);
  const savedTour = savedTourState?.userId === userId ? savedTourState.progress : null;
  const operatorTour = useMemo(() => access?.allowed ? getPlatformOperatorTour(access.capabilities) : undefined, [access]);
  useEffect(() => {
    if (!token || !access?.allowed) return;
    let current = true;
    void getPlatformTourProgress(token).then(({ progress }) => { if (current) setSavedTourState({ userId, progress }); }).catch(() => undefined);
    return () => { current = false; };
  }, [access?.allowed, token, userId]);
  const persistOperatorTour = useCallback(async (progress: { tourId: string; stepIndex: number; status: "running" | "skipped" | "completed" }) => {
    const result = await savePlatformTourProgress(token, { ...progress, tourId: "platform-operator" });
    setSavedTourState({ userId, progress: result.progress });
  }, [token, userId]);
  const routeCapabilities: Record<string, string> = { "": "platform.dashboard.read", tenants: "platform.tenants.read", users: "platform.users.read", usage: "platform.usage.read", health: "platform.health.read", audit: "platform.audit.read", support: "platform.support.manage", settings: "platform.settings.manage" };
  const hasRouteCapability = access?.capabilities[routeCapabilities[route.area] ?? ""] === true;
  const [search, setSearch] = useState(""); const [filter, setFilter] = useState(""); const [tenantIndustry,setTenantIndustry]=useState("");const [tenantPlan,setTenantPlan]=useState("");const [page, setPage] = useState(1); const [notice, setNotice] = useState(""); const [actionBusy, setActionBusy] = useState(false);
  const read = useCallback(async () => {
    if (!token || !access?.allowed || !hasRouteCapability) return null;
    switch (route.area) {
      case "": return getPlatformOverview(token);
      case "tenants": return route.id ? getPlatformTenant(token, route.id) : getPlatformTenants(token, { page, pageSize: 25, search, status: filter || undefined, industry:tenantIndustry||undefined, plan:tenantPlan||undefined });
      case "users": return route.id ? getPlatformUser(token, route.id) : getPlatformUsers(token, { page, pageSize: 25, search });
      case "usage": return getPlatformUsage(token, { page, pageSize: 50, sort: filter || "storage_bytes" });
      case "health": return getPlatformHealth(token);
      case "audit": return getPlatformAudit(token, { page, pageSize: 50, search });
      case "support": return route.id ? getPlatformSupportCase(token, route.id) : getPlatformSupport(token, { page, pageSize: 25, status: filter || undefined, search });
      case "settings": return getPlatformSettings(token);
      default: return null;
    }
  }, [token, access?.allowed, hasRouteCapability, route.area, route.id, page, search, filter,tenantIndustry,tenantPlan]);
  const { data, error, busy, refresh, setError } = useAdminData<PlatformRow | null>(read, userId);
  useEffect(() => { setPage(1); setNotice(""); }, [route.area, route.id, search, filter,tenantIndustry,tenantPlan]);
  async function mutate(action: () => Promise<unknown>, message: string) { setActionBusy(true); setError(""); setNotice(""); try { await action(); setNotice(message); await refresh(); } catch (e) { setError(getErr(e)); } finally { setActionBusy(false); } }
  if (authLoading || !session) return <PlatformShell active=""><main className="mx-auto max-w-6xl px-4 py-10"><p role="status" className={card}>Checking your sign-in session…</p></main></PlatformShell>;
  if (access === null) return <PlatformShell active=""><main className="mx-auto max-w-6xl px-4 py-10"><p role="status" className={card}>Verifying platform authorization…</p></main></PlatformShell>;
  if (!access.allowed) return <PlatformShell active="" capabilities={access.capabilities}><main className="mx-auto max-w-3xl px-4 py-16"><section className={`${card} border-warning/25`}><p className={eyebrow}>PLATFORM ACCESS REQUIRED</p><h1 className="mt-3 font-display text-2xl font-semibold text-foreground">This account is not a platform operator.</h1><p className="mt-3 text-sm leading-6 text-slate-500">Platform privileges are assigned through a trusted, audited operator process. Workspace ownership, agency access and subscription plans do not grant platform administration.</p>{accessError && <p role="alert" className="mt-4 text-xs text-danger">{accessError}</p>}<Link to="/app" className={`${secondary} mt-5`}>Return to Tandem Ads</Link></section></main></PlatformShell>;
  const activeHref = route.area ? `/app/platform-admin/${route.area}` : "/app/platform-admin";
  const heading: Record<string, string> = { "": "Operations command center", tenants: route.id ? "Tenant operations" : "Tenant directory", users: route.id ? "Account overview" : "User directory", usage: "Workspace usage", health: "Service health", audit: "Platform audit center", support: route.id ? "Support case" : "Support operations", settings: "Platform settings" };
  return <PlatformShell active={activeHref} capabilities={access.capabilities}><main className="mx-auto max-w-[1500px] space-y-6 px-4 py-6 sm:px-7 lg:px-9 lg:py-8"><header className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className={eyebrow}>SAAS OPERATIONS · PRIVATE CONSOLE</p><h1 className="mt-2 font-display text-3xl font-semibold tracking-[-.04em] text-foreground sm:text-4xl" data-tour-id="platform-page-title">{heading[route.area] ?? "Platform operations"}</h1><p className="mt-2 max-w-2xl text-xs leading-6 text-slate-500">Operational metadata is sourced from the current database. Customer campaign and creative content is not exposed in this console.</p></div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full border border-electric/25 bg-electric/5 px-3 py-2 text-[9px] font-semibold uppercase tracking-wide text-electric-bright">Local platform controls</span>{operatorTour && <button aria-label={savedTour?.status === "running" ? "Resume platform tour" : "Start or restart platform tour"} className={secondary} data-tour-id="platform-tour-start" onClick={() => { setTourOpen(true); }} type="button">{savedTour?.status === "running" ? "Resume guided tour" : savedTour?.status === "completed" ? "Restart guided tour" : "Guided tour"}</button>}<button className={secondary} onClick={() => void refresh()} disabled={busy}>{busy ? "Refreshing…" : "Refresh"}</button></div></header>
    {error && <p role="alert" className="rounded-xl border border-danger/25 bg-danger/10 p-3 text-xs text-danger">{error}</p>}{notice && <p role="status" className="rounded-xl border border-emerald-500/25 bg-emerald-500/10 p-3 text-xs text-emerald-500">{notice}</p>}
    {!hasRouteCapability && <section role="status" className={`${card} border-warning/25`}><p className={eyebrow}>AREA NOT AVAILABLE</p><h2 className="mt-2 text-base font-semibold text-foreground">This operator role cannot open this console area.</h2><p className="mt-2 text-xs leading-5 text-slate-500">The server checks platform capabilities separately for every area. Use one of the visible authorized sections.</p></section>}
    {hasRouteCapability && route.area === "" && data && <OverviewPanel value={data} />}
    {hasRouteCapability && route.area === "tenants" && (route.id ? <TenantDetail value={obj(data)} actionBusy={actionBusy} canManage={access.capabilities["platform.tenants.manage"]===true} run={mutate} /> : <TenantDirectory value={obj(data)} search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} industry={tenantIndustry} setIndustry={setTenantIndustry} plan={tenantPlan} setPlan={setTenantPlan} page={page} setPage={setPage} />)}
    {hasRouteCapability && route.area === "users" && (route.id ? <UserDetail value={obj(data)} /> : <UserDirectory value={obj(data)} search={search} setSearch={setSearch} page={page} setPage={setPage} />)}
    {hasRouteCapability && route.area === "usage" && <UsagePanel value={obj(data)} filter={filter} setFilter={setFilter} page={page} setPage={setPage} />}
    {hasRouteCapability && route.area === "health" && <HealthPanel value={obj(data)} />}
    {hasRouteCapability && route.area === "audit" && <AuditPanel value={obj(data)} search={search} setSearch={setSearch} page={page} setPage={setPage} />}
    {hasRouteCapability && route.area === "support" && (route.id ? <SupportDetail value={obj(data)} actionBusy={actionBusy} run={mutate} /> : <SupportPanel value={obj(data)} search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} page={page} setPage={setPage} actionBusy={actionBusy} run={mutate} />)}
    {hasRouteCapability && route.area === "settings" && <SettingsPanel value={obj(data)} actionBusy={actionBusy} run={mutate} />}
    {tourOpen && operatorTour && <TourOverlay onClose={() => setTourOpen(false)} onSaveProgress={persistOperatorTour} startIndex={savedTour?.status === "running" ? savedTour.stepIndex : 0} token={token} tour={operatorTour} />}
  </main></PlatformShell>;
}

function OverviewPanel({ value }: { value: Obj }) {
  const items = rows(value.recent_admin_events); const statuses = rows(value.subscriptions_by_status); const plans = rows(value.subscriptions_by_plan); const industries = rows(value.industries);
  const trialing=number(statuses.find(x=>text(x.status)==="trialing")?.count); const createdMonth=number(value.workspaces_created_last_30_days);
  return <><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Registered workspaces" value={value.workspaces_total} detail={`${count(value.workspaces_active)} active · live database records`} /><Metric label="Registered accounts" value={value.users_total} detail="Auth user records · no presence claims" /><Metric label="Workspace campaigns" value={value.campaigns_total} detail="Stored drafts and demo records" /><Metric label="Saved creatives" value={value.creatives_total} detail="Creative project metadata" /></section><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Trial workspaces" value={trialing} detail="Current subscription records"/><Metric label="Created in last 30 days" value={createdMonth} detail="Current database creation timestamps"/><Metric label="Stored asset data" value={`${(number(value.storage_bytes)/1073741824).toFixed(2)} GB`} detail="Private workspace assets · current total"/><Metric label="Open support cases" value={value.support_open} detail="Open, in progress or waiting"/></section><section className="grid gap-4 xl:grid-cols-[1.2fr_.8fr]"><div className={card}><div className="flex flex-wrap items-end justify-between gap-3"><div><p className={eyebrow}>WORKSPACE HEALTH MIX</p><h2 className="mt-2 text-sm font-semibold text-foreground">Operational status</h2></div><p className="text-[10px] text-slate-500">As of {date(value.as_of)}</p></div><div className="mt-5 grid grid-cols-3 gap-3"><div className="rounded-xl border border-stroke bg-surface-muted p-4"><p className={eyebrow}>Active</p><p className="mt-2 font-display text-2xl font-semibold text-foreground">{count(value.workspaces_active)}</p></div><div className="rounded-xl border border-stroke bg-surface-muted p-4"><p className={eyebrow}>Review</p><p className="mt-2 font-display text-2xl font-semibold text-foreground">{count(value.workspaces_under_review)}</p></div><div className="rounded-xl border border-stroke bg-surface-muted p-4"><p className={eyebrow}>Restricted</p><p className="mt-2 font-display text-2xl font-semibold text-foreground">{count(value.workspaces_suspended)}</p></div></div><div className="mt-5 flex flex-wrap gap-2"><Link className={secondary} to="/app/platform-admin/tenants">Browse tenants</Link><Link className={secondary} to="/app/platform-admin/support">Support queue · {count(value.support_open)} open</Link><Link className={secondary} to="/app/platform-admin/health">Check service health</Link></div></div><div className={card}><p className={eyebrow}>SIMULATED SUBSCRIPTIONS</p><h2 className="mt-2 text-sm font-semibold text-foreground">Plan distribution</h2><p className="mt-1 text-[10px] text-warning">Demo billing records only. No collected revenue.</p><div className="mt-4 space-y-3">{plans.length ? plans.map((plan) => <div key={text(plan.plan_id)} className="flex items-center justify-between gap-4 border-b border-stroke pb-2 text-xs"><span className="text-foreground">{title(text(plan.plan_id))}</span><span className="font-semibold text-electric-bright">{count(plan.count)}</span></div>) : <p className="py-4 text-xs text-slate-500">No workspace subscriptions are recorded.</p>}</div><div className="mt-5"><p className={eyebrow}>SUBSCRIPTION STATES</p><div className="mt-3 flex flex-wrap gap-2">{statuses.map((entry) => <span key={text(entry.status)} className="rounded-lg border border-stroke px-3 py-2 text-[10px] text-slate-500">{title(text(entry.status))} · {count(entry.count)}</span>)}</div></div></div></section><section className="grid gap-4 xl:grid-cols-2"><div className={card}><p className={eyebrow}>INDUSTRY DISTRIBUTION</p><div className="mt-4 space-y-3">{industries.length ? industries.slice(0, 10).map((entry) => <div className="flex items-center justify-between gap-4" key={text(entry.industry_key)}><span className="truncate text-xs text-foreground">{title(text(entry.industry_key))}</span><span className="text-xs tabular-nums text-slate-500">{count(entry.count)}</span></div>) : <p className="py-5 text-xs text-slate-500">No workspace industry records are available.</p>}</div></div><div className={card}><p className={eyebrow}>RECENT PRIVILEGED ACTIVITY</p><div className="mt-3 divide-y divide-stroke">{items.length ? items.map((event) => <div key={text(event.id)} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="text-xs font-medium text-foreground">{title(text(event.action))}</p><p className="mt-1 text-[10px] text-slate-500">{title(text(event.actor_role))} · {text(event.target_type)} · {text(event.target_id)}</p></div><div className="text-right"><State value={event.outcome} /><p className="mt-1 text-[9px] text-slate-600">{date(event.created_at)}</p></div></div>) : <p className="py-8 text-xs text-slate-500">No platform operations have been recorded.</p>}</div></div></section></>;
}

function Pager({ page, setPage, value }: { page: number; setPage: (n: number) => void; value: Obj }) { const total = number(value.total); const size = number(value.page_size) || 25; const pages = Math.max(1, Math.ceil(total / size)); return <div className="mt-4 flex items-center justify-between text-[10px] text-slate-500"><span>{count(total)} records · page {page} of {pages}</span><div className="flex gap-2"><button className={secondary} disabled={page <= 1} onClick={() => setPage(page - 1)}>Previous</button><button className={secondary} disabled={page >= pages} onClick={() => setPage(page + 1)}>Next</button></div></div>; }
function FilterBar({ search, setSearch, extra }: { search: string; setSearch: (v: string) => void; extra?: ReactNode }) { return <div className="mb-4 flex flex-col gap-2 sm:flex-row"><input aria-label="Search records" className={`${inputClass} sm:max-w-sm`} placeholder="Search by name or identifier" value={search} onChange={(e) => setSearch(e.target.value)} />{extra}</div>; }
function TenantDirectory({ value, search, setSearch, filter, setFilter, industry, setIndustry, plan, setPlan, page, setPage }: { value: Obj; search: string; setSearch: (v: string) => void; filter: string; setFilter: (v: string) => void; industry: string; setIndustry: (v:string)=>void; plan:string; setPlan:(v:string)=>void; page: number; setPage: (v: number) => void }) {
  const list = unwrapItems(value); return <section className={card}><div className="mb-4 flex flex-wrap items-end justify-between gap-3"><div><p className={eyebrow}>SAFE TENANT METADATA</p><h2 className="mt-2 text-sm font-semibold text-foreground">Registered workspaces</h2></div><p className="text-[10px] text-slate-500">Names, industry, counts and status only</p></div><FilterBar search={search} setSearch={setSearch} extra={<div className="grid flex-1 gap-2 sm:grid-cols-3"><select aria-label="Workspace lifecycle" className={inputClass} value={filter} onChange={(e) => setFilter(e.target.value)}><option value="">All lifecycle states</option>{["ACTIVE","UNDER_REVIEW","SUSPENSION_PENDING","SUSPENDED","RESTORATION_PENDING","ARCHIVED"].map((state) => <option key={state}>{state}</option>)}</select><select aria-label="Industry filter" className={inputClass} value={industry} onChange={e=>setIndustry(e.target.value)}><option value="">All industries</option>{INDUSTRIES.map(item=><option key={item.key} value={item.key}>{item.name}</option>)}</select><select aria-label="Plan filter" className={inputClass} value={plan} onChange={e=>setPlan(e.target.value)}><option value="">All plans</option>{["free_trial","starter","growth","agency","enterprise","legacy_transition"].map(item=><option key={item} value={item}>{title(item)}</option>)}</select></div>} /><Table items={list} columns={[["Workspace", (x) => <Link className="font-semibold text-electric-bright hover:underline" to={`/app/platform-admin/tenants/${text(x.id)}`}>{text(x.name)}</Link>],["Type", (x) => title(text(x.operating_mode,"business"))],["Industry", (x) => title(text(x.industry_key))],["Lifecycle", (x) => <State value={x.workspace_status} />],["Plan", (x) => title(text(x.plan_id, "Unconfigured"))],["Members", (x) => count(x.membership_count)],["Campaigns", (x) => count(x.campaign_count)],["Storage", (x) => `${(number(x.storage_bytes) / 1024 / 1024).toFixed(1)} MB`]]} /><Pager value={value} page={page} setPage={setPage} /></section>;
}
function TenantDetail({ value, actionBusy, canManage, run }: { value: Obj; actionBusy: boolean; canManage:boolean; run: (fn: () => Promise<unknown>, message: string) => Promise<void> }) {
  const {session}=useAuth();const token=session?.access_token??"";
  const workspace = obj(value.workspace); const countsObj = obj(value.counts); const subscription = obj(value.subscription); const [reason, setReason] = useState(""); const [next, setNext] = useState(""); const lifecycle = rows(value.lifecycle_history); const billing = rows(value.billing_events); const support = rows(value.support_cases); const status = text(workspace.status, "ACTIVE");
  const permitted: Record<string, string[]> = { ACTIVE: ["UNDER_REVIEW", "SUSPENSION_PENDING"], UNDER_REVIEW: ["ACTIVE", "SUSPENSION_PENDING"], SUSPENSION_PENDING: ["SUSPENDED"], SUSPENDED: ["RESTORATION_PENDING"], RESTORATION_PENDING: ["ACTIVE"] };
  const metrics: Array<[string, unknown]> = [["Members",countsObj.members],["Campaign drafts",countsObj.campaigns],["Creative projects",countsObj.creatives],["Private asset storage",`${(number(countsObj.storage_bytes)/1048576).toFixed(1)} MB`]];
  const historySections: Array<[string,Obj[]]> = [["Lifecycle history",lifecycle],["Recent support cases",support]];
  return <div className="space-y-4"><section className={`${card} flex flex-wrap items-start justify-between gap-4`}><div><p className={eyebrow}>TENANT ID · {text(workspace.id)}</p><h2 className="mt-2 font-display text-2xl font-semibold text-foreground">{text(workspace.name, "Workspace")}</h2><p className="mt-2 text-xs text-slate-500">{title(text(workspace.industry_key))} · created {date(workspace.created_at)} · {workspace.agency_mode === true ? "Agency workspace" : "Independent business workspace"}</p></div><State value={status} /></section><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{metrics.map(([label,value])=><div key={label} className={card}><p className={eyebrow}>{label}</p><p className="mt-3 text-xl font-semibold text-foreground">{typeof value === "number" ? count(value) : String(value ?? "—")}</p></div>)}</section><section className="grid gap-4 xl:grid-cols-[.8fr_1.2fr]"><div className={card}><p className={eyebrow}>SUBSCRIPTION STATE · SIMULATION</p><h3 className="mt-2 text-sm font-semibold text-foreground">{title(text(subscription.plan_id,"No configured plan"))}</h3><p className="mt-2 text-xs text-slate-500">{title(text(subscription.status,"No subscription"))} · source {text(subscription.source,"—")}</p><p className="mt-2 text-[10px] text-slate-600">Period end {date(subscription.period_end)} · trial end {date(subscription.trial_ends_at)}</p><p className="mt-5 rounded-xl border border-warning/20 bg-warning/5 p-3 text-[10px] leading-5 text-warning">Billing records are simulated. No payment was processed and no revenue is reported.</p><h4 className={`${eyebrow} mt-5`}>Recent subscription events</h4><div className="mt-2 divide-y divide-stroke">{billing.length ? billing.slice(0,6).map((item,i)=><p key={i} className="py-2 text-[10px] text-slate-500">{title(text(item.event_type))} · {title(text(item.prior_state))} → {title(text(item.next_state))} · {date(item.created_at)}</p>) : <p className="py-3 text-[10px] text-slate-500">No billing events recorded.</p>}</div></div><div className={card}><p className={eyebrow}>LIFECYCLE CONTROL</p>{canManage?<><p className="mt-2 text-xs leading-5 text-slate-500">Status changes are explicit and audited. Suspension preserves records; read/recovery behavior follows the local platform policy.</p><label className="mt-4 block text-[10px] font-medium text-slate-500">Next permitted transition</label><select aria-label="Next permitted transition" className={`${inputClass} mt-2`} value={next} onChange={(e) => setNext(e.target.value)}><option value="">Select a valid transition</option>{(permitted[status] ?? []).map((item) => <option key={item}>{item}</option>)}</select><textarea aria-label="Lifecycle reason" className={`${inputClass} mt-2 min-h-20 py-3`} placeholder="Record a clear operational reason (8–500 chars)" value={reason} onChange={(e) => setReason(e.target.value)} /><button className={`${primary} mt-3`} disabled={actionBusy || !next || reason.trim().length < 8} onClick={() => void run(() => setPlatformTenantStatus(token,text(workspace.id),next,reason.trim()), `Tenant transition recorded: ${title(next)}.`)}>{actionBusy ? "Saving…" : "Record transition"}</button><button className={`${secondary} ml-2 mt-3`} disabled={actionBusy || reason.trim().length < 8} onClick={() => void run(() => flagPlatformTenant(token,text(workspace.id),reason.trim()), "Tenant flagged for operational review.")}>Flag for review</button></>:<p className="mt-2 text-xs leading-6 text-slate-500">Read-only access. This role cannot change workspace operational status.</p>}<p className="mt-4 text-[10px] text-slate-600">A business workspace does not inherit platform privileges or expose its private campaign content here.</p></div></section><section className="grid gap-4 xl:grid-cols-2">{historySections.map(([heading,items])=><div key={heading} className={card}><p className={eyebrow}>{heading}</p><div className="mt-3 divide-y divide-stroke">{items.length ? items.map((item,index)=><div key={text(item.id,String(index))} className="py-3"><p className="text-xs font-medium text-foreground">{title(text(item.previous_status, text(item.subject)))}{item.next_status ? ` → ${title(text(item.next_status))}` : ""}</p><p className="mt-1 text-[10px] text-slate-500">{text(item.reason, title(text(item.category)))} · {date(item.created_at)}</p></div>) : <p className="py-6 text-xs text-slate-500">No history is available.</p>}</div></div>)}</section></div>;
}

function UserDirectory({ value, search, setSearch, page, setPage }: { value: Obj; search: string; setSearch: (v: string) => void; page: number; setPage: (v: number) => void }) { return <section className={card}><p className={eyebrow}>AUTH ACCOUNT METADATA</p><h2 className="mb-4 mt-2 text-sm font-semibold text-foreground">Registered users</h2><FilterBar search={search} setSearch={setSearch} /><Table items={unwrapItems(value)} columns={[["Account",(x)=><Link className="text-electric-bright hover:underline" to={`/app/platform-admin/users/${text(x.id)}`}>{text(x.full_name,text(x.email))}</Link>],["Email",(x)=>text(x.email)],["Created",(x)=>date(x.created_at)],["Email confirmation",(x)=><State value={x.email_confirmed_at?"ACTIVE":"UNCONFIRMED"}/>],["Memberships",(x)=>count(x.membership_count)],["Platform operator",(x)=><State value={x.platform_operator?"ACTIVE":"NONE"}/>]]} /><Pager value={value} page={page} setPage={setPage} /></section>; }
function UserDetail({ value }: { value: Obj }) { const account=obj(value.user);return <div className="grid gap-4 xl:grid-cols-[.8fr_1.2fr]"><section className={card}><p className={eyebrow}>AUTH ACCOUNT</p><h2 className="mt-3 text-lg font-semibold text-foreground">{text(account.full_name,text(account.email))}</h2><p className="mt-2 text-xs text-slate-500">{text(account.email)}</p><p className="mt-2 text-[10px] text-slate-600">User ID {text(account.id)}</p><p className="mt-4 text-[10px] text-slate-500">Created {date(account.created_at)} · confirmed {date(account.email_confirmed_at)}</p><p className="mt-5 text-[10px] leading-5 text-slate-500">Credential hashes, sessions, refresh tokens and provider secrets are not exposed to platform operators.</p></section><section className={card}><p className={eyebrow}>WORKSPACE MEMBERSHIPS</p><div className="mt-3 divide-y divide-stroke">{rows(value.memberships).length?rows(value.memberships).map((membership,index)=><div key={`${text(membership.workspace_id)}-${index}`} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="text-xs font-medium text-foreground">{text(membership.workspace_name)}</p><p className="mt-1 text-[10px] text-slate-500">{title(text(membership.role))} · {date(membership.created_at)}</p></div><State value={membership.workspace_status}/></div>):<p className="py-8 text-xs text-slate-500">No workspace membership records.</p>}</div><p className={`${eyebrow} mt-5`}>PLATFORM ROLE HISTORY</p><div className="mt-2 divide-y divide-stroke">{rows(value.platform_roles).length?rows(value.platform_roles).map((role,index)=><p key={index} className="py-2 text-[10px] text-slate-500">{title(text(role.role_key))} · granted {date(role.granted_at)} · {role.revoked_at?`revoked ${date(role.revoked_at)}`:"currently assigned"}</p>):<p className="py-3 text-xs text-slate-500">No platform roles assigned.</p>}</div></section></div>; }
function UsagePanel({ value, filter, setFilter, page, setPage }: { value: Obj; filter: string; setFilter: (v: string) => void; page:number; setPage:(v:number)=>void }) { const cols: Array<[string,(x:Obj)=>ReactNode]> = [["Workspace",x=>text(x.name)],["Industry",x=>title(text(x.industry_key))],["Plan",x=>title(text(x.plan_id,"Unconfigured"))],["Status",x=><State value={x.workspace_status}/>],["Seats",x=>count(x.seats)],["Campaigns",x=>count(x.campaigns)],["Creatives",x=>count(x.creatives)],["Storage",x=>`${(number(x.storage_bytes)/1048576).toFixed(1)} MB`],["Automation runs",x=>count(x.automation_runs)],["Reports",x=>count(x.reports)]];return <section className={card}><div className="mb-4 flex flex-wrap items-end justify-between gap-3"><div><p className={eyebrow}>CURRENT RECORD COUNTS</p><h2 className="mt-2 text-sm font-semibold text-foreground">Workspace resource usage</h2><p className="mt-1 text-[10px] text-slate-500">Source: saved business and metering records. Browser-only exports are not represented as server-metered use.</p></div><select className={`${inputClass} max-w-52`} aria-label="Sort usage" value={filter||"storage_bytes"} onChange={e=>setFilter(e.target.value)}>{[["storage_bytes","Storage"],["campaigns","Campaigns"],["creatives","Creatives"],["members","Seats"],["name","Name"]].map(([key,label])=><option key={key} value={key}>Sort by {label}</option>)}</select></div><Table items={unwrapItems(value)} columns={cols}/><Pager value={value} page={page} setPage={setPage}/></section>; }
function HealthPanel({ value }: { value: Obj }) { const entries=Object.entries(value).filter(([key])=>key!=="checkedAt");return <><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{entries.map(([key,raw])=>{const item=obj(raw);return <article key={key} className={card}><div className="flex items-start justify-between gap-2"><div><p className={eyebrow}>{title(key)}</p><p className="mt-3 text-lg font-semibold text-foreground">{title(text(item.status,"UNKNOWN"))}</p></div><State value={item.status}/></div><p className="mt-3 text-[10px] leading-5 text-slate-500">{text(item.source,"No health probe is configured for this component.")}</p>{typeof item.checkedAt === "string"&&<p className="mt-2 text-[9px] text-slate-600">Checked {date(item.checkedAt)}</p>}</article>;})}</section><p className="text-[10px] leading-5 text-slate-500">No uptime percentages or infrastructure resource estimates are inferred. UNKNOWN means there is no measured source for that component.</p></>; }
function AuditPanel({ value, search, setSearch, page, setPage }: { value: Obj; search: string; setSearch: (v: string) => void; page: number; setPage: (v: number) => void }) { return <section className={card}><p className={eyebrow}>PRIVILEGED OPERATIONS</p><h2 className="mb-4 mt-2 text-sm font-semibold text-foreground">Append-only platform activity</h2><FilterBar search={search} setSearch={setSearch}/><Table items={unwrapItems(value)} columns={[["Action",x=>title(text(x.action))],["Actor",x=>`${text(x.actor_role)} · ${text(x.actor_user_id)}`],["Target",x=>`${text(x.target_type)} · ${text(x.target_id)}`],["Outcome",x=><State value={x.outcome}/>],["Reason",x=><span className="line-clamp-2 max-w-sm text-[10px] text-slate-500">{text(x.reason)}</span>],["Time",x=>date(x.created_at)]]}/><Pager value={value} page={page} setPage={setPage}/></section>; }
function SupportPanel({ value, search, setSearch, filter, setFilter, page, setPage, actionBusy, run }: { value: Obj; search: string; setSearch: (v: string) => void; filter: string; setFilter: (v: string) => void; page: number; setPage: (n:number)=>void; actionBusy: boolean; run: (fn:()=>Promise<unknown>,msg:string)=>Promise<void> }) {
  const {session}=useAuth();const token=session?.access_token??"";
  const [open,setOpen]=useState(false); const [form,setForm]=useState({workspaceId:"",category:"permissions",priority:"normal",subject:"",description:""});
  return <section className={card}><div className="mb-4 flex flex-wrap items-end justify-between gap-3"><div><p className={eyebrow}>INTERNAL SUPPORT QUEUE</p><h2 className="mt-2 text-sm font-semibold text-foreground">Cases and consent requests</h2></div><button className={primary} onClick={()=>setOpen(!open)}>{open?"Close form":"Open support case"}</button></div>{open&&<div className="mb-5 grid gap-2 rounded-xl border border-stroke bg-surface-muted p-4 md:grid-cols-2"><input aria-label="Workspace ID" className={inputClass} placeholder="Workspace ID (optional)" value={form.workspaceId} onChange={e=>setForm({...form,workspaceId:e.target.value})}/><select aria-label="Support category" className={inputClass} value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{["authentication","onboarding","permissions","billing","storage","campaigns","reports","agency","other"].map(x=><option key={x}>{x}</option>)}</select><input aria-label="Case subject" className={inputClass} placeholder="Subject" value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})}/><select aria-label="Case priority" className={inputClass} value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{["low","normal","high","urgent"].map(x=><option key={x}>{x}</option>)}</select><textarea aria-label="Case description" className={`${inputClass} min-h-24 py-3 md:col-span-2`} placeholder="Operational description" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/><button className={`${primary} md:col-span-2`} disabled={actionBusy||form.subject.trim().length<4||form.description.trim().length<10} onClick={()=>void run(()=>createPlatformSupportCase(token,{workspaceId:form.workspaceId||null,category:form.category,priority:form.priority,subject:form.subject,description:form.description}),"Support case created.")}>Create internal case</button></div>}<FilterBar search={search} setSearch={setSearch} extra={<select className={inputClass} value={filter} aria-label="Support status" onChange={e=>setFilter(e.target.value)}><option value="">All case states</option>{["OPEN","IN_PROGRESS","WAITING_ON_CUSTOMER","RESOLVED","CLOSED"].map(x=><option key={x}>{x}</option>)}</select>}/><Table items={unwrapItems(value)} columns={[["Case",x=><Link className="font-semibold text-electric-bright" to={`/app/platform-admin/support/${text(x.id)}`}>{text(x.subject)}</Link>],["Workspace",x=>text(x.workspace_id,"Platform")],["Category",x=>title(text(x.category))],["Priority",x=>title(text(x.priority))],["Status",x=><State value={x.status}/>],["Updated",x=>date(x.updated_at)]]}/><Pager value={value} page={page} setPage={setPage}/></section>;
}
function SupportDetail({ value, actionBusy, run }: { value: Obj; actionBusy: boolean; run:(fn:()=>Promise<unknown>,msg:string)=>Promise<void> }) { const {session}=useAuth();const token=session?.access_token??"";const c=obj(value.case);const [status,setStatus]=useState(text(c.status,"OPEN"));const [note,setNote]=useState("");const [resolution,setResolution]=useState(text(c.resolution_summary,""));const requests=rows(value.access_requests);return <div className="grid gap-4 xl:grid-cols-[1.1fr_.9fr]"><section className={card}><p className={eyebrow}>CASE {text(c.id)}</p><h2 className="mt-2 text-lg font-semibold text-foreground">{text(c.subject)}</h2><p className="mt-2 text-xs leading-6 text-slate-500">{text(c.description)}</p><div className="mt-4 flex flex-wrap gap-2"><State value={c.status}/><State value={c.priority}/><span className="rounded-full border border-stroke px-3 py-1 text-[9px] text-slate-500">{title(text(c.category))}</span></div><label className="mt-5 block text-[10px] text-slate-500">Case status</label><select className={`${inputClass} mt-2`} value={status} onChange={e=>setStatus(e.target.value)}>{["OPEN","IN_PROGRESS","WAITING_ON_CUSTOMER","RESOLVED","CLOSED"].map(x=><option key={x}>{x}</option>)}</select><textarea aria-label="Private internal note" className={`${inputClass} mt-2 min-h-20 py-3`} placeholder="Internal note (private from customer)" value={note} onChange={e=>setNote(e.target.value)}/><textarea aria-label="Resolution summary" className={`${inputClass} mt-2 min-h-20 py-3`} placeholder="Resolution summary" value={resolution} onChange={e=>setResolution(e.target.value)}/><button className={`${primary} mt-3`} disabled={actionBusy} onClick={()=>void run(()=>updatePlatformSupportCase(token,text(c.id),{status,internalNote:note||null,resolution:resolution||null}),"Support case updated.")}>Save case</button><p className="mt-4 rounded-xl border border-warning/20 bg-warning/5 p-3 text-[10px] leading-5 text-warning">This case does not grant access to customer campaigns, assets or reports. Access remains denied by default.</p><div className="mt-6"><p className={eyebrow}>LIMITED ASSISTANCE REQUESTS</p>{requests.length?requests.map((r,i)=><div className="mt-3 rounded-xl border border-stroke p-3" key={text(r.id,String(i))}><p className="text-xs font-medium text-foreground">{stringItems(r.scope_keys).map(title).join(", ")}</p><p className="mt-1 text-[10px] text-slate-500">{text(r.status)} · expires {date(r.expires_at)}</p><p className="mt-1 text-[10px] text-slate-500">{text(r.reason)}</p></div>):<p className="mt-3 text-xs text-slate-500">No consent requests are attached.</p>}</div></section><AccessRequestForm caseId={text(c.id)} run={run} actionBusy={actionBusy}/></div>;
}
function AccessRequestForm({caseId,run,actionBusy}:{caseId:string;run:(fn:()=>Promise<unknown>,msg:string)=>Promise<void>;actionBusy:boolean}) { const {session}=useAuth();const token=session?.access_token??"";const [scope,setScope]=useState(["workspace_metadata"]);const [reason,setReason]=useState("");return <section className={card}><p className={eyebrow}>CONSENT-BASED ASSISTANCE</p><h2 className="mt-2 text-sm font-semibold text-foreground">Request limited diagnostic scope</h2><p className="mt-2 text-[10px] leading-5 text-slate-500">A customer can approve or reject. This milestone records consent but does not provide direct content access.</p><div className="mt-4 space-y-2">{["workspace_metadata","campaign_status","creative_metadata","report_metadata","storage_diagnostics"].map(key=><label className="flex items-center gap-2 text-[10px] text-slate-500" key={key}><input type="checkbox" checked={scope.includes(key)} onChange={e=>setScope(e.target.checked?[...scope,key]:scope.filter(x=>x!==key))}/>{title(key)}</label>)}</div><textarea className={`${inputClass} mt-4 min-h-20 py-3`} value={reason} onChange={e=>setReason(e.target.value)} placeholder="Explain the requested access (8–500 chars)"/><button className={`${primary} mt-3`} disabled={actionBusy||scope.length===0||reason.trim().length<8} onClick={()=>void run(()=>requestPlatformSupportAccess(token,caseId,{scopeKeys:scope,reason}),"Customer consent request recorded; no content access was granted.")}>Request customer consent</button></section>; }

function SettingsPanel({ value, actionBusy, run }: { value: Obj; actionBusy: boolean; run:(fn:()=>Promise<unknown>,msg:string)=>Promise<void> }) {
  const {session}=useAuth();const token=session?.access_token??"";const flags=rows(value.feature_flags);const settings=useMemo(()=>obj(value.settings),[value.settings]);const [reason,setReason]=useState("");const [drafts,setDrafts]=useState<Record<string,string>>({});const [localError,setLocalError]=useState("");
  useEffect(()=>setDrafts(Object.fromEntries(Object.entries(settings).map(([key,item])=>[key,typeof item==="string"?item:String(item??"")]))),[settings]);
  function parseSetting(key:string):unknown { const raw=drafts[key]??""; if(key==="default_trial_days"){const parsed=Number(raw);if(!Number.isInteger(parsed)||parsed<0||parsed>90)throw new Error("Trial duration must be a whole number from 0 to 90.");return parsed;} if(key==="public_registration_mode"){if(!["enabled","invite_only","disabled"].includes(raw))throw new Error("Choose a valid registration mode.");return raw;} return raw.trim(); }
  return <div className="grid gap-4 xl:grid-cols-2"><section className={card}><p className={eyebrow}>ROLLOUT FLAGS</p><h2 className="mt-2 text-sm font-semibold text-foreground">Workspace module availability</h2><p className="mt-2 text-[10px] leading-5 text-slate-500">A flag can restrict a feature. It never grants a role, entitlement, or permission to call external providers.</p><div className="mt-4 divide-y divide-stroke">{flags.map(flag=><div key={text(flag.flag_key)} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="text-xs font-medium text-foreground">{title(text(flag.flag_key))}</p><p className="mt-1 text-[9px] text-slate-500">Updated {date(flag.updated_at)}</p></div><button className={secondary} disabled={actionBusy||reason.trim().length<8} onClick={()=>void run(()=>updatePlatformFeatureFlag(token,text(flag.flag_key),!flag.enabled,reason),`Feature flag ${flag.enabled?"disabled":"enabled"}.`)}>{flag.enabled?"Enabled · disable":"Disabled · enable"}</button></div>)}</div></section><section className={card}><p className={eyebrow}>SAFE OPERATING PREFERENCES</p><h2 className="mt-2 text-sm font-semibold text-foreground">Validated platform settings</h2><p className="mt-1 text-[10px] leading-5 text-slate-500">These values are stored as platform preferences. Registration-mode enforcement through Supabase Auth is not configured by this console.</p><div className="mt-4 space-y-3">{Object.entries(settings).map(([key,current])=><div key={key} className="rounded-xl border border-stroke p-3"><label className="text-xs font-semibold text-foreground" htmlFor={`setting-${key}`}>{title(key)}</label>{key==="public_registration_mode"?<select id={`setting-${key}`} className={`${inputClass} mt-2`} value={drafts[key]??String(current)} onChange={e=>setDrafts({...drafts,[key]:e.target.value})}>{["enabled","invite_only","disabled"].map(mode=><option key={mode} value={mode}>{title(mode)}</option>)}</select>:<input id={`setting-${key}`} className={`${inputClass} mt-2`} value={drafts[key]??String(current)} onChange={e=>setDrafts({...drafts,[key]:e.target.value})} type={key==="default_trial_days"?"number":"text"} min={key==="default_trial_days"?0:undefined} max={key==="default_trial_days"?90:undefined} />}</div>)}</div><textarea aria-label="Configuration change reason" className={`${inputClass} mt-4 min-h-16 py-3`} value={reason} onChange={e=>setReason(e.target.value)} placeholder="A reason is required for changes"/><div className="mt-3 flex flex-wrap gap-2">{Object.keys(settings).map(key=><button key={key} className={secondary} disabled={actionBusy||reason.trim().length<8||drafts[key]===String(settings[key])} onClick={()=>{try{setLocalError("");const parsed=parseSetting(key);void run(()=>updatePlatformSetting(token,key,parsed,reason),`${title(key)} saved.`);}catch(error){setLocalError(getErr(error));}}}>Save {title(key)}</button>)}</div>{localError&&<p role="alert" className="mt-3 text-xs text-danger">{localError}</p>}<p className="mt-2 text-[10px] text-slate-500">Sensitive secrets and environment variables are never editable here.</p></section></div>;
}

export function WorkspaceSupportPage() {
  const {session}=useAuth();const {activeWorkspace}=useWorkspace();const token=session?.access_token??"";const workspaceId=activeWorkspace?.id??"";const [data,setData]=useState<{cases:PlatformRow[];accessRequests:PlatformRow[]}|null>(null);const [error,setError]=useState("");const [notice,setNotice]=useState("");const [busy,setBusy]=useState(false);const [form,setForm]=useState({category:"permissions",subject:"",description:""});
  const refresh=useCallback(async()=>{if(!token||!workspaceId)return;setError("");try{setData(await getWorkspaceSupport(token,workspaceId));}catch(e){setError(getErr(e));}},[token,workspaceId]);useEffect(()=>{void refresh();},[refresh]);
  async function act(fn:()=>Promise<unknown>,message:string){setBusy(true);setError("");setNotice("");try{await fn();setNotice(message);await refresh();}catch(e){setError(getErr(e));}finally{setBusy(false);}}
  return <WorkspaceAppLayout title="Workspace support"><main className="mx-auto max-w-5xl space-y-5 px-4 py-8 sm:px-7"><header><p className={eyebrow}>WORKSPACE SUPPORT</p><h1 className="mt-2 font-display text-3xl font-semibold text-foreground">Get help from Tandem Ads</h1><p className="mt-2 text-xs leading-6 text-slate-500">Requests are stored in-app. Support staff do not automatically receive access to your campaign, creative or report content.</p></header>{error&&<p role="alert" className="rounded-xl bg-danger/10 p-3 text-xs text-danger">{error}</p>}{notice&&<p role="status" className="rounded-xl bg-electric/10 p-3 text-xs text-electric-bright">{notice}</p>}<div className="grid gap-4 lg:grid-cols-[.8fr_1.2fr]"><section className={card}><p className={eyebrow}>NEW SUPPORT REQUEST</p><label className="mt-4 block text-[10px] text-slate-500">Category</label><select className={`${inputClass} mt-2`} value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{["authentication","onboarding","permissions","billing","storage","campaigns","reports","agency","other"].map(x=><option key={x}>{x}</option>)}</select><input className={`${inputClass} mt-3`} placeholder="Short subject" value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})}/><textarea className={`${inputClass} mt-3 min-h-32 py-3`} placeholder="Describe the issue" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/><button className={`${primary} mt-3 w-full`} disabled={busy||form.subject.trim().length<4||form.description.trim().length<10||!workspaceId} onClick={()=>void act(()=>createWorkspaceSupport(token,workspaceId,form),"Your support request is recorded in Tandem Ads.")}>Submit support request</button></section><section className={card}><p className={eyebrow}>RECENT REQUESTS</p><div className="mt-3 divide-y divide-stroke">{data?.cases.length?data.cases.map((c,i)=><div key={text(c.id,String(i))} className="py-3"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-medium text-foreground">{text(c.subject)}</p><State value={c.status}/></div><p className="mt-1 text-[10px] text-slate-500">{title(text(c.category))} · opened {date(c.created_at)}</p></div>):<p className="py-8 text-xs text-slate-500">No support requests for this workspace.</p>}</div><p className={`${eyebrow} mt-6`}>ACCESS CONSENT REQUESTS</p><div className="mt-2 space-y-2">{data?.accessRequests.length?data.accessRequests.map((request,i)=><div key={text(request.id,String(i))} className="rounded-xl border border-warning/20 bg-warning/5 p-3"><p className="text-xs font-medium text-foreground">Limited support diagnostics requested</p><p className="mt-1 text-[10px] text-slate-500">Scope: {stringItems(request.scope_keys).map(title).join(", ")} · expires {date(request.expires_at)}</p><p className="mt-2 text-[10px] text-warning">Approval only records consent. It does not grant access to customer content in this milestone.</p>{text(request.status)==="PENDING"&&<div className="mt-3 flex gap-2"><button className={primary} disabled={busy} onClick={()=>void act(()=>decideWorkspaceSupportAccess(token,workspaceId,text(request.id),"APPROVED"),"Consent recorded. No customer-content access was granted.")}>Approve request</button><button className={secondary} disabled={busy} onClick={()=>void act(()=>decideWorkspaceSupportAccess(token,workspaceId,text(request.id),"REJECTED"),"Request rejected.")}>Reject</button></div>}</div>):<p className="py-4 text-xs text-slate-500">No pending support access requests.</p>}</div></section></div></main></WorkspaceAppLayout>;
}
